#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=9

TENANT_ID="cdf89f94-8c88-48fc-b11c-dd24af4380b4"
SITE_ACCOUNT="twopointwebsite"
CONTAINERS=(published working revisions series)
BUILD_CONTAINERS=(published series)
REPOS=(tw0po1nt/twopoint-website-staging tw0po1nt/twopoint-website)
GITHUB_ISSUER="https://token.actions.githubusercontent.com"
GITHUB_AUDIENCE="api://AzureADTokenExchange"

ok() { printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$1"; }

banner "Post store: Azure setup"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Sign in to Azure"
say "The wizard uses the Azure CLI for each change. It asks before each change."
if az account show >/dev/null 2>&1 && az storage account list --query "[0].name" -o tsv >/dev/null 2>&1; then
  note "You are already signed in as $(az account show --query user.name -o tsv)."
else
  step "A browser window opens for the Azure sign-in."
  pause "Press Enter to start the sign-in."
  az login --tenant "$TENANT_ID" >/dev/null
fi
SUBSCRIPTION_ID=$(az account show --query id -o tsv)
note "Subscription: $(az account show --query name -o tsv) ($SUBSCRIPTION_ID)"
DEVELOPER_ID=$(az ad signed-in-user show --query id -o tsv)
note "Your object ID: $DEVELOPER_ID"
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Name the post store"
say "The post store is a new storage account, separate from $SITE_ACCOUNT."
say "It goes in the resource group and the region of $SITE_ACCOUNT."
SITE_RG=$(az storage account list --query "[?name=='$SITE_ACCOUNT'].resourceGroup | [0]" -o tsv)
SITE_LOCATION=$(az storage account list --query "[?name=='$SITE_ACCOUNT'].primaryLocation | [0]" -o tsv)
[[ -n "$SITE_RG" ]] || { warn "Cannot find $SITE_ACCOUNT in this subscription."; exit 1; }
note "Resource group: $SITE_RG. Region: $SITE_LOCATION."
ask STORE_ACCOUNT "Storage account name (Enter for 'twopointposts'):"
STORE_ACCOUNT="${STORE_ACCOUNT:-twopointposts}"
ask BUILD_IDENTITY "Build identity name (Enter for 'id-twopoint-site-build'):"
BUILD_IDENTITY="${BUILD_IDENTITY:-id-twopoint-site-build}"
step "Storage account: $STORE_ACCOUNT"
step "Build identity: $BUILD_IDENTITY"
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Make the storage account"
say "Blob public access is off for the whole account."
say "Shared key access is off too, so each request must use an Entra ID sign-in."
if az storage account show -n "$STORE_ACCOUNT" -g "$SITE_RG" >/dev/null 2>&1; then
  note "The account already exists."
else
  AVAILABLE=$(az storage account check-name -n "$STORE_ACCOUNT" --query nameAvailable -o tsv)
  [[ "$AVAILABLE" == "true" ]] || { warn "The name '$STORE_ACCOUNT' is not available. Run the wizard again with a different name."; exit 1; }
  if confirm "Make the storage account '$STORE_ACCOUNT' in '$SITE_RG' ($SITE_LOCATION)?"; then
    az storage account create -n "$STORE_ACCOUNT" -g "$SITE_RG" -l "$SITE_LOCATION" \
      --sku Standard_LRS --kind StorageV2 --https-only true --min-tls-version TLS1_2 \
      --allow-blob-public-access false --allow-shared-key-access false >/dev/null
    ok "made the storage account $STORE_ACCOUNT"
  else
    warn "The other stages need the account. Run the wizard again to continue."
    exit 1
  fi
fi
PUBLIC_ACCESS=$(az storage account show -n "$STORE_ACCOUNT" -g "$SITE_RG" --query allowBlobPublicAccess -o tsv)
if [[ "$PUBLIC_ACCESS" == "false" ]]; then
  ok "Blob public access is off."
elif confirm "Blob public access is not off. Turn it off for the whole account?"; then
  az storage account update -n "$STORE_ACCOUNT" -g "$SITE_RG" --allow-blob-public-access false >/dev/null
  ok "turned off blob public access"
else
  SKIPPED+=("Turn off blob public access: az storage account update -n $STORE_ACCOUNT -g $SITE_RG --allow-blob-public-access false")
fi
STORE_ID=$(az storage account show -n "$STORE_ACCOUNT" -g "$SITE_RG" --query id -o tsv)
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Make the four containers"
for container in "${CONTAINERS[@]}"; do
  EXISTS=$(az storage container-rm exists --storage-account "$STORE_ACCOUNT" -g "$SITE_RG" -n "$container" --query exists -o tsv)
  if [[ "$EXISTS" == "true" ]]; then
    note "The container '$container' already exists."
  else
    az storage container-rm create --storage-account "$STORE_ACCOUNT" -g "$SITE_RG" -n "$container" \
      --public-access off >/dev/null
    ok "made the container $container"
  fi
done
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Give your account access to the posts"
say "Storage Blob Data Contributor on the account lets you:"
step "run pull for the local stage,"
step "run the upload script,"
step "upload a post by hand until the admin is live."
DEVELOPER_ROLES=$(az role assignment list --assignee "$DEVELOPER_ID" --scope "$STORE_ID" --include-inherited \
  --query "[?roleDefinitionName=='Storage Blob Data Contributor' || roleDefinitionName=='Storage Blob Data Owner'] | length(@)" -o tsv)
if [[ "${DEVELOPER_ROLES:-0}" -gt 0 ]]; then
  note "Your account can already read and write the post store. Nothing to do."
elif confirm "Give your account 'Storage Blob Data Contributor' on $STORE_ACCOUNT?"; then
  az role assignment create --assignee-object-id "$DEVELOPER_ID" --assignee-principal-type User \
    --role "Storage Blob Data Contributor" --scope "$STORE_ID" >/dev/null
  ok "assigned Storage Blob Data Contributor"
else
  SKIPPED+=("Assign Storage Blob Data Contributor on $STORE_ACCOUNT to $DEVELOPER_ID")
fi
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Make the build identity"
say "site.yml and the CI site job sign in as this managed identity to pull the posts."
if az identity show -n "$BUILD_IDENTITY" -g "$SITE_RG" >/dev/null 2>&1; then
  note "The identity already exists."
elif confirm "Make the managed identity '$BUILD_IDENTITY' in '$SITE_RG'?"; then
  az identity create -n "$BUILD_IDENTITY" -g "$SITE_RG" -l "$SITE_LOCATION" >/dev/null
  ok "made the identity $BUILD_IDENTITY"
else
  warn "The other stages need the identity. Run the wizard again to continue."
  exit 1
fi
BUILD_CLIENT_ID=$(az identity show -n "$BUILD_IDENTITY" -g "$SITE_RG" --query clientId -o tsv)
BUILD_PRINCIPAL_ID=$(az identity show -n "$BUILD_IDENTITY" -g "$SITE_RG" --query principalId -o tsv)
step "Client ID: $BUILD_CLIENT_ID"
step "Principal ID: $BUILD_PRINCIPAL_ID"
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Let the build identity read published and series"
say "The build identity gets Storage Blob Data Reader on published and series only."
say "It cannot read a draft, a pending edit, or a revision."
for container in "${BUILD_CONTAINERS[@]}"; do
  SCOPE="$STORE_ID/blobServices/default/containers/$container"
  READER_ROLES=$(az role assignment list --assignee "$BUILD_PRINCIPAL_ID" --scope "$SCOPE" \
    --query "[?roleDefinitionName=='Storage Blob Data Reader'] | length(@)" -o tsv)
  if [[ "${READER_ROLES:-0}" -gt 0 ]]; then
    note "The identity can already read '$container'."
  else
    az role assignment create --assignee-object-id "$BUILD_PRINCIPAL_ID" --assignee-principal-type ServicePrincipal \
      --role "Storage Blob Data Reader" --scope "$SCOPE" >/dev/null
    ok "assigned Storage Blob Data Reader on $container"
  fi
done
WIDE_ROLES=$(az role assignment list --assignee "$BUILD_PRINCIPAL_ID" --all \
  --query "[?starts_with(roleDefinitionName, 'Storage Blob Data') && !contains(scope, '/containers/')].scope" -o tsv)
if [[ -n "$WIDE_ROLES" ]]; then
  warn "The identity has a Storage Blob Data role above the container level:"
  while IFS= read -r scope; do note "  $scope"; done <<< "$WIDE_ROLES"
  warn "Then it can read working and revisions. Remove that role in the portal."
  SKIPPED+=("Remove the Storage Blob Data role of $BUILD_IDENTITY above the container level")
fi
pause

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Trust the GitHub runs"
say "Each site repo gets two federated credentials on the build identity:"
step "pull_request: the CI site job on each PR."
step "ref:refs/heads/main: a workflow_dispatch run of site.yml, and a push to main."
for repo in "${REPOS[@]}"; do
  short="${repo#*/}"
  for kind in pull-request main; do
    name="$short-$kind"
    if [[ "$kind" == "pull-request" ]]; then subject="repo:$repo:pull_request"; else subject="repo:$repo:ref:refs/heads/main"; fi
    if az identity federated-credential show --name "$name" --identity-name "$BUILD_IDENTITY" -g "$SITE_RG" >/dev/null 2>&1; then
      note "The credential '$name' already exists."
    else
      az identity federated-credential create --name "$name" --identity-name "$BUILD_IDENTITY" -g "$SITE_RG" \
        --issuer "$GITHUB_ISSUER" --subject "$subject" --audiences "$GITHUB_AUDIENCE" >/dev/null
      ok "added $name ($subject)"
    fi
  done
done
pause

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Give the build identity to the site repos"
say "Each site repo gets these values for the Azure sign-in of the build:"
step "secret AZURE_BUILD_CLIENT_ID = $BUILD_CLIENT_ID"
step "secret AZURE_TENANT_ID = $TENANT_ID, if the repo does not have it"
step "secret AZURE_SUBSCRIPTION_ID = $SUBSCRIPTION_ID, if the repo does not have it"
step "variable POST_STORE_ACCOUNT = $STORE_ACCOUNT"
if confirm "Write these values to ${REPOS[*]}?"; then
  for repo in "${REPOS[@]}"; do
    note "$repo"
    EXISTING_SECRETS=$(gh secret list --repo "$repo" --json name --jq '.[].name' 2>/dev/null || true)
    GH_REPO="$repo" set_secret AZURE_BUILD_CLIENT_ID "$BUILD_CLIENT_ID"
    grep -qx AZURE_TENANT_ID <<< "$EXISTING_SECRETS" || GH_REPO="$repo" set_secret AZURE_TENANT_ID "$TENANT_ID"
    grep -qx AZURE_SUBSCRIPTION_ID <<< "$EXISTING_SECRETS" || GH_REPO="$repo" set_secret AZURE_SUBSCRIPTION_ID "$SUBSCRIPTION_ID"
    GH_REPO="$repo" set_var POST_STORE_ACCOUNT "$STORE_ACCOUNT"
  done
else
  SKIPPED+=("Set AZURE_BUILD_CLIENT_ID=$BUILD_CLIENT_ID and POST_STORE_ACCOUNT=$STORE_ACCOUNT in ${REPOS[*]}")
fi
pause

# ── Check ─────────────────────────────────────────────────────────────────
_clear
printf '\n%s%s▸ Check the post store%s\n' "$BOLD" "$BLUE" "$RESET"
az storage account show -n "$STORE_ACCOUNT" -g "$SITE_RG" \
  --query "{account:name, blobPublicAccess:allowBlobPublicAccess, sharedKeyAccess:allowSharedKeyAccess}" -o table
printf '\n'
az storage container-rm list --storage-account "$STORE_ACCOUNT" -g "$SITE_RG" \
  --query "[].{container:name, publicAccess:publicAccess}" -o table
printf '\n'
az role assignment list --assignee "$BUILD_PRINCIPAL_ID" --all \
  --query "[].{role:roleDefinitionName, scope:scope}" -o table
printf '\n'
az identity federated-credential list --identity-name "$BUILD_IDENTITY" -g "$SITE_RG" \
  --query "[].{name:name, subject:subject}" -o table
printf '\n'
for container in "${CONTAINERS[@]}"; do
  CODE=$(curl -s -o /dev/null -w '%{http_code}' \
    "https://$STORE_ACCOUNT.blob.core.windows.net/$container?restype=container&comp=list" || true)
  if [[ "$CODE" == "200" ]]; then
    warn "An anonymous list of '$container' gives 200. The container is public."
  else
    ok "An anonymous list of '$container' gives $CODE."
  fi
done
printf '\n'
note "A new role can take up to 10 minutes to take effect."
note "Then upload the posts: see scripts/migrate-posts/README.md."
pause

finish
}

run_wizard "$@"; exit
